  return ORDERS.get(id) ?? "no such order";
}

const orderId: OrderId = "ord_1001";
const customerId: CustomerId = "cus_01";

console.log(`${orderId}: ${getOrder(orderId)}`);
console.log(`${customerId}: ${getOrder(customerId)}`);

