function parseOrderId(s: string): OrderId | null {
  const id = s.trim();
  return isOrderId(id) ? id : null;
}

for (const input of [" ord_1001 ", "ord_12", "ORD_1001", "cus_01"]) {
  const parsed = parseOrderId(input);
