export type OrderId = string & { readonly __brand: "OrderId" };
export type CustomerId = string & { readonly __brand: "CustomerId" };

export function isOrderId(s: string): s is OrderId {
  return /^ord_\d{4}$/.test(s);
}

export function isCustomerId(s: string): s is CustomerId {
  return /^cus_\d{2}$/.test(s);
}

const ORDERS = [
  { id: "ord_1001", customerId: "cus_01" },
  { id: "ord_1002", customerId: "cus_02" },
  { id: "ord_1003", customerId: "cus_01" },
  { id: "ord_99", customerId: "cus_01" },
];

