steps.body:
A brand can stand for any rule a value follows, not only an ID format: an email that was trimmed and lowercased, an amount in whole cents, a percentage from 0 to 100. The function that creates one is called a smart constructor. It checks the input, cleans it up when that makes sense, and returns the brand, or `null` when the input breaks the rule. Every function that takes the branded type can then trust it without checking again.

Numbers can be branded too, with one catch: arithmetic always gives back a plain `number`, even when both sides are branded.

```typescript
type Cents = number & { readonly __brand: "Cents" };

function isCents(n: number): n is Cents {
  return Number.isInteger(n) && n >= 0;
}

const price = 1299;
const tax = 104;
if (isCents(price) && isCents(tax)) {
  const total = price + tax;
  //    ^? const total: number
  console.log(total); // 1403
}
```

So a function that promises `Cents` from arithmetic checks the result again before it returns it. For input from outside, return `null` when a check fails. For values your own code computes, where a failure means a bug, throw instead.

examples.code:
type Email = string & { readonly __brand: "Email" };

function isEmail(s: string): s is Email {
  return /^[^@\s]+@[^@\s]+$/.test(s);
}

function parseEmail(s: string): Email | null {
  const email = s.trim().toLowerCase();
  return isEmail(email) ? email : null;
}

function sendWelcome(to: Email): string {
  return `welcome mail sent to ${to}`;
}

for (const input of ["  Ada@Example.com ", "grace@navy.mil", "not an email", "a@b@c"]) {
  const email = parseEmail(input);
  console.log(email === null ? `invalid: "${input}"` : sendWelcome(email));
}

type Cents = number & { readonly __brand: "Cents" };

function isCents(n: number): n is Cents {
  return Number.isInteger(n) && n >= 0;
}

function cents(n: number): Cents {
  if (!isCents(n)) {
    throw new Error(`not a whole number of cents: ${n}`);
  }
  return n;
}

function toCents(dollars: string): Cents | null {
  if (!/^\d+\.\d{2}$/.test(dollars)) return null;
  const amount = Math.round(Number(dollars) * 100);
  return isCents(amount) ? amount : null;
}

function addCents(a: Cents, b: Cents): Cents {
  return cents(a + b);
}

console.log(Number("1.15") * 100);
console.log(toCents("1.15"), toCents("12.50"), toCents("12.5"), toCents("abc"));

const price = toCents("12.50");
const shipping = toCents("1.15");
if (price !== null && shipping !== null) {
  console.log(`total: ${addCents(price, shipping)} cents`);
}

declare const brand: unique symbol;
type Brand<T, B extends string> = T & { readonly [brand]: B };

type Sku = Brand<string, "Sku">;
//   ^? type Sku = string & { readonly [brand]: "Sku"; }
type Grams = Brand<number, "Grams">;
//   ^? type Grams = number & { readonly [brand]: "Grams"; }

function isSku(s: string): s is Sku {
  return /^[A-Z]{3}-\d{3}$/.test(s);
}

function isGrams(n: number): n is Grams {
  return Number.isInteger(n) && n > 0;
}

function label(sku: Sku, weight: Grams): string {
  return `${sku} weighs ${weight} g`;
}

const items: [sku: string, weight: number][] = [
  ["MUG-001", 350],
  ["mug-2", 350],
  ["TEA-014", 0],
];

for (const [sku, weight] of items) {
  console.log(isSku(sku) && isGrams(weight) ? label(sku, weight) : `skipped ${sku}`);
}

