import { readFileSync } from "node:fs";

export type Cents = number & { readonly __brand: "Cents" };

export function isCents(n: number): n is Cents {
  return Number.isInteger(n) && n >= 0;
}

export function cents(n: number): Cents {
  if (!isCents(n)) {
    throw new Error(`not a whole number of cents: ${n}`);
  }
  return n;
}

export function toCents(dollars: string): Cents | null {
  if (!/^\d+\.\d{2}$/.test(dollars)) return null;
  const amount = Math.round(Number(dollars) * 100);
  return isCents(amount) ? amount : null;
}

export function addCents(a: Cents, b: Cents): Cents {
  return cents(a + b);
}

export function formatCents(c: Cents): string {
  return `$${(c / 100).toFixed(2)}`;
}

const lines = readFileSync(0, "utf8").trim().split("\n");
let total = cents(0);
for (const line of lines) {
  const price = toCents(line);
  if (price === null) {
    console.log(`invalid price: ${line}`);
  } else {
    total = addCents(total, price);
  }
}
console.log(`total: ${formatCents(total)}`);

steps.body:
Brands are one case of a bigger idea: put a rule in a type, and code that breaks the rule doesn't compile. If a function needs at least one number, require a tuple with a first element:

```typescript types
type NonEmptyArray<T> = [T, ...T[]];

const one: NonEmptyArray<number> = [7];
const three: NonEmptyArray<number> = [7, 8, 9];
```

`[T, ...T[]]` is a tuple whose first element must exist, followed by any number of others. An empty array doesn't fit, so the function never has to handle one, and `xs[0]` is a `T`, never `undefined`.

The same thinking covers other rules. If an invoice may only go to a verified email address, make verified a type of its own, and let only the verifying function produce it. If an order must not change once it's placed, make it `Readonly`, and write each update as a function that returns a new order. A check that would otherwise be repeated all over the codebase becomes one type, and the checker applies it everywhere.

examples.code:
type NonEmptyArray<T> = [T, ...T[]];

function isNonEmpty<T>(xs: readonly T[]): xs is NonEmptyArray<T> {
  return xs.length > 0;
}

function highest(bids: NonEmptyArray<number>): number {
  let best = bids[0];
  //  ^? let best: number
  for (const bid of bids) {
    if (bid > best) best = bid;
  }
  return best;
}

const auctions: Record<string, number[]> = {
  lamp: [120, 95, 140],
  chair: [],
  clock: [60],
};

for (const [item, bids] of Object.entries(auctions)) {
  console.log(isNonEmpty(bids) ? `${item}: highest bid ${highest(bids)}` : `${item}: no bids`);
}

examples.explanation:
Inside `highest`, `bids[0]` is a `number`, not `number | undefined`, as the bubble shows, because the tuple type says the first element exists. So the function needs no empty check and no made-up starting value. A plain `number[]` can't be passed in: the loop checks each list with `isNonEmpty` first, and the guard narrows `bids` to `NonEmptyArray<number>`. The empty case is handled once, at the call, where printing `no bids` makes sense. An empty array literal is rejected outright:

```typescript error
type NonEmptyArray<T> = [T, ...T[]];

function highest(bids: NonEmptyArray<number>): number {
  return Math.max(...bids);
}

console.log(highest([]));
```

examples.code:
type Email = string & { readonly __brand: "Email" };
type VerifiedEmail = Email & { readonly __verified: true };

function isEmail(s: string): s is Email {
  return /^[^@\s]+@[^@\s]+$/.test(s);
}

const CODES = new Map([["ada@example.com", "4821"]]);

function isVerified(email: Email, code: string): email is VerifiedEmail {
  return CODES.get(email) === code;
}

function verify(email: Email, code: string): VerifiedEmail | null {
  return isVerified(email, code) ? email : null;
}

function sendInvoice(to: VerifiedEmail, totalCents: number): string {
  return `invoice for ${totalCents} cents sent to ${to}`;
}

const attempts: [address: string, code: string][] = [
  ["ada@example.com", "4821"],
  ["ada@example.com", "1234"],
  ["not-an-email", "4821"],
];

for (const [address, code] of attempts) {
  if (!isEmail(address)) {
    console.log(`${address}: not an email`);
    continue;
  }
  const verified = verify(address, code);
  console.log(verified === null ? `${address}: not verified` : sendInvoice(verified, 1299));
}

examples.explanation:
`VerifiedEmail` adds a second brand on top of `Email`. Every verified email is still an `Email`, so it fits wherever an `Email` does, but a plain `Email` isn't a `VerifiedEmail`. The only code that produces one is `verify`, through the `isVerified` guard, so `sendInvoice` can't be reached with an address that skipped verification. Try it, and the checker names the missing brand:

```typescript error
type Email = string & { readonly __brand: "Email" };
type VerifiedEmail = Email & { readonly __verified: true };

function isEmail(s: string): s is Email {
  return /^[^@\s]+@[^@\s]+$/.test(s);
}

function sendInvoice(to: VerifiedEmail, totalCents: number): string {
  return `invoice for ${totalCents} cents sent to ${to}`;
}

const address: string = "ada@example.com";
if (isEmail(address)) {
  console.log(sendInvoice(address, 1299));
}
```

examples.code:
type OrderLine = Readonly<{ sku: string; qty: number; priceCents: number }>;
type Order = Readonly<{ id: string; lines: readonly OrderLine[] }>;

function addLine(order: Order, line: OrderLine): Order {
  return { ...order, lines: [...order.lines, line] };
}

function totalCents(order: Order): number {
  return order.lines.reduce((sum, line) => sum + line.qty * line.priceCents, 0);
}

const placed: Order = { id: "ord_1001", lines: [{ sku: "MUG-001", qty: 2, priceCents: 1299 }] };
const updated = addLine(placed, { sku: "TEA-014", qty: 1, priceCents: 850 });

console.log(`placed: ${placed.lines.length} line, ${totalCents(placed)} cents`);
console.log(`updated: ${updated.lines.length} lines, ${totalCents(updated)} cents`);

examples.explanation:
`Readonly` makes every property of the order read-only, and `readonly OrderLine[]` takes away `push` and every other method that changes the array. So no code can change a placed order in place, which matters when other code may still hold it. `addLine` builds a new order instead: the spread copies `id`, and the new `lines` array holds the old lines plus the new one. `placed` is unchanged, as the first line shows. Changing the order directly doesn't compile:

```typescript error
type OrderLine = Readonly<{ sku: string; qty: number; priceCents: number }>;
type Order = Readonly<{ id: string; lines: readonly OrderLine[] }>;

const placed: Order = { id: "ord_1001", lines: [] };
placed.lines.push({ sku: "MUG-001", qty: 2, priceCents: 1299 });
placed.id = "ord_2002";
console.log(placed.id);
```

Like brands, `readonly` only exists for the checker, so it costs nothing at run time.

