import { readFileSync } from "node:fs";

export type NonEmptyArray<T> = [T, ...T[]];

export function isNonEmpty<T>(xs: readonly T[]): xs is NonEmptyArray<T> {
  return xs.length > 0;
}

export function average(xs: NonEmptyArray<number>): number {
  return xs.reduce((sum, x) => sum + x, 0) / xs.length;
}

const numbers = readFileSync(0, "utf8")
  .split(/\s+/)
  .filter((s) => s !== "")
  .map(Number);

console.log(isNonEmpty(numbers) ? `average: ${average(numbers).toFixed(2)}` : "no numbers");

